#!/bin/sh
# Builds the Java trust store for the bundled Lavalink: the JVM's default CAs + the certificate of Rift's audio bridge.
# Runs once per `docker compose up` inside the Lavalink image (it has keytool). The bridge is the voice server Lavalink
# connects to; its certificate is generated by the Rift worker into the shared `sink-tls` volume.
set -eu
CERT=/sink/cert.pem
i=0
while [ ! -s "$CERT" ] && [ "$i" -lt 90 ]; do i=$((i + 1)); sleep 1; done
[ -s "$CERT" ] || { echo "Rift audio bridge certificate not found at $CERT (is the worker running?)" >&2; exit 1; }
JAVA_BIN="$(readlink -f "$(command -v java)")"
CACERTS="$(dirname "$JAVA_BIN")/../lib/security/cacerts"
[ -f "$CACERTS" ] || { echo "Could not find the JVM cacerts at $CACERTS" >&2; exit 1; }
cp "$CACERTS" /trust/trust.jks
chmod u+w /trust/trust.jks
keytool -importcert -noprompt -alias rift-bridge -file "$CERT" -keystore /trust/trust.jks -storepass changeit
echo "Lavalink trust store ready."
